From a9ae43d1050168a9d517cfb952c167c35af3bcf0 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 14:29:04 +0100
Subject: [PATCH] sqlite: Don't bring back scores of resources that were just
 forgotten

When stats were deleted while a score update for the same resource was
still queued, the update ran right after and recreated the cache entry,
so the forgotten file came back in recent lists. Drop such queued updates.

BUG: 444393
---
 .../sqlite/ResourceScoreMaintainer.cpp        | 22 +++++++++++++++++++
 .../plugins/sqlite/ResourceScoreMaintainer.h  |  1 +
 src/service/plugins/sqlite/StatsPlugin.cpp    |  2 ++
 3 files changed, 25 insertions(+)

diff --git a/src/service/plugins/sqlite/ResourceScoreMaintainer.cpp b/src/service/plugins/sqlite/ResourceScoreMaintainer.cpp
index 7ebb2c96..97b0ad56 100644
--- a/src/service/plugins/sqlite/ResourceScoreMaintainer.cpp
+++ b/src/service/plugins/sqlite/ResourceScoreMaintainer.cpp
@@ -17,6 +17,7 @@
 #include <utils/d_ptr_implementation.h>

 // Local
+#include "Database.h"
 #include "ResourceScoreCache.h"
 #include "StatsPlugin.h"

@@ -123,3 +124,24 @@ void ResourceScoreMaintainer::processResource(const QString &resource, const QSt

     d->processResourcesTimer.start();
 }
+
+void ResourceScoreMaintainer::cancelProcessing(const QString &activity, const QString &application, const QString &resourcePattern)
+{
+    const auto pattern = Common::starPatternToRegex(resourcePattern);
+
+    for (auto activityIt = d->scheduledResources.begin(); activityIt != d->scheduledResources.end(); ++activityIt) {
+        if (!activity.isEmpty() && activityIt.key() != activity) {
+            continue;
+        }
+
+        for (auto applicationIt = activityIt->begin(); applicationIt != activityIt->end(); ++applicationIt) {
+            if (!application.isEmpty() && applicationIt.key() != application) {
+                continue;
+            }
+
+            applicationIt->removeIf([&pattern](const QString &resource) {
+                return pattern.match(resource).hasMatch();
+            });
+        }
+    }
+}
diff --git a/src/service/plugins/sqlite/ResourceScoreMaintainer.h b/src/service/plugins/sqlite/ResourceScoreMaintainer.h
index b564cd77..415c351e 100644
--- a/src/service/plugins/sqlite/ResourceScoreMaintainer.h
+++ b/src/service/plugins/sqlite/ResourceScoreMaintainer.h
@@ -25,6 +25,7 @@ public:
     ~ResourceScoreMaintainer() override;

     void processResource(const QString &resource, const QString &application);
+    void cancelProcessing(const QString &activity, const QString &application, const QString &resourcePattern);

 private:
     ResourceScoreMaintainer();
diff --git a/src/service/plugins/sqlite/StatsPlugin.cpp b/src/service/plugins/sqlite/StatsPlugin.cpp
index f8171419..4ee5503e 100644
--- a/src/service/plugins/sqlite/StatsPlugin.cpp
+++ b/src/service/plugins/sqlite/StatsPlugin.cpp
@@ -557,6 +557,8 @@ void StatsPlugin::DeleteStatsForResource(const QString &activity, const QString
         "AND initiatingAgent = COALESCE(:initiatingAgent, initiatingAgent) "
         "AND targettedResource LIKE :targettedResource ESCAPE '\\'");

+    ResourceScoreMaintainer::self()->cancelProcessing(usedActivity.toString(), initiatingAgent.toString(), resource);
+
     const auto pattern = Common::starPatternToLike(resource);

     Utils::exec(*resourcesDatabase(), Utils::FailOnError, removeResourceInfoQuery, ":targettedResource", pattern);
-- 
2.53.0

From db04b16c8f7a4a0ee5a9650afa3a1640d0af1caa Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 14:29:09 +0100
Subject: [PATCH] kded: Forget recent files from a vault when it is locked

Files opened from a vault stayed in recently-used.xbel and in the
activity stats after locking, so their names and paths kept showing in
launchers and jump lists. Remove those entries whenever a vault closes.

BUG: 444393
---
 kded/engine/vault.cpp | 42 +++++++++++++++++++++++++++++++++++++++---
 1 file changed, 39 insertions(+), 3 deletions(-)

diff --git a/kded/engine/vault.cpp b/kded/engine/vault.cpp
index f488d00..7dca70a 100644
--- a/kded/engine/vault.cpp
+++ b/kded/engine/vault.cpp
@@ -6,17 +6,23 @@

 #include "vault.h"

+#include <QDBusConnection>
+#include <QDBusMessage>
+#include <QDBusMetaType>
 #include <QDir>
 #include <QFutureWatcher>
-#include <QDBusMetaType>
 #include <QMessageBox>
-#include <QUrl>
 #include <QPointer>
+#include <QUrl>

 #include <KConfig>
 #include <KConfigGroup>
 #include <KSharedConfig>
 #include <QRegularExpression>
+#include <QStandardPaths>
+#include <QXmlStreamReader>
+
+#include <KRecentDocument>

 #include <processcore/process.h>
 #include <processcore/processes.h>
@@ -104,6 +110,34 @@ public:
         Q_EMIT q->messageChanged(message);
     }

+    void forgetRecentFiles() const
+    {
+        const QString prefix = data->mountPoint.data() + QLatin1Char('/');
+
+        QFile xbel(QStandardPaths::writableLocation(QStandardPaths::GenericDataLocation) + QStringLiteral("/recently-used.xbel"));
+        QList<QUrl> urls;
+        if (xbel.open(QIODevice::ReadOnly)) {
+            QXmlStreamReader xml(&xbel);
+            while (!xml.atEnd()) {
+                if (xml.readNext() == QXmlStreamReader::StartElement && xml.name() == QLatin1String("bookmark")) {
+                    const QUrl url = QUrl::fromEncoded(xml.attributes().value(QLatin1String("href")).toLatin1());
+                    if (url.isLocalFile() && url.toLocalFile().startsWith(prefix)) {
+                        urls << url;
+                    }
+                }
+            }
+        }
+        for (const auto &url : std::as_const(urls)) {
+            KRecentDocument::removeFile(url);
+        }
+
+        auto message = QDBusMessage::createMethodCall(QStringLiteral("org.kde.ActivityManager"),
+                                                      QStringLiteral("/ActivityManager/Resources/Scoring"),
+                                                      QStringLiteral("org.kde.ActivityManager.ResourcesScoring"),
+                                                      QStringLiteral("DeleteStatsForResource"));
+        message << QStringLiteral(":any") << QStringLiteral(":any") << prefix + QLatin1Char('*');
+        QDBusConnection::sessionBus().asyncCall(message);
+    }

     void writeConfiguration()
     {
@@ -185,8 +219,10 @@ public:
                     Q_EMIT q->isOpenedChanged(newStatus == VaultInfo::Opened);

                     // lock the mountpoint when the vault is closed
-                    if (newStatus == VaultInfo::Closed)
+                    if (newStatus == VaultInfo::Closed) {
                         data->backend->lockMountPoint(data->mountPoint, true);
+                        forgetRecentFiles();
+                    }
                 }

                 if (oldStatus == VaultInfo::NotInitialized //
